import itertools

N = 4
V = [(r, c) for r in range(N) for c in range(N)] # Vertices (row, col), 0-indexed

def is_king_adjacent(v1, v2):
    """Checks if two vertices are adjacent in the King's graph (sharing vertex or side)."""
    r1, c1 = v1
    r2, c2 = v2
    return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1 and (r1 != r2 or c1 != c2)

def is_independent_set(subset):
    """Checks if a subset of vertices is an independent set."""
    for v1, v2 in itertools.combinations(subset, 2):
        if is_king_adjacent(v1, v2):
            return False
    return True

valid_sets = []
# Iterate through all 2^16 possible subsets
for i in range(1 << (N*N)):
    subset = []
    for j in range(N*N):
        if (i >> j) & 1:
            subset.append(V[j])

    if is_independent_set(subset):
        # Filter for sets where size |S| >= 2
        if len(subset) >= 2:
            valid_sets.append(subset)

# Output the count of valid sets and some examples/max size for verification
num_valid_sets = len(valid_sets)
max_size = 0
for s in valid_sets:
    max_size = max(max_size, len(s))

print(f"Total number of valid sets S (|S| >= 2): {num_valid_sets}")
print(f"Maximum size of a valid set S: {max_size}")

# Smallest valid sets (size 2)
print("\nExamples of smallest valid sets (size 2):")
examples_size_2 = [s for s in valid_sets if len(s) == 2]
for i in range(min(5, len(examples_size_2))):
    print(examples_size_2[i])

